Path('lib/features/paths/widgets/path_edit_sheet.dart').write_text("import 'package:counter/core/widgets/app_button.dart';\nimport 'package:counter/data/paths/path_repository.dart';\nimport 'package:flutter/material.dart';\n\nclass PathEditDraft {\n  const PathEditDraft({required this.name, required this.goal});\n\n  final String name;\n  final String goal;\n}\n\nclass PathStageEditDraft {\n  const PathStageEditDraft({\n    required this.title,\n    required this.completionCriteria,\n  });\n\n  final String title;\n  final String completionCriteria;\n}\n\nclass PathActionEditDraft {\n  const PathActionEditDraft({\n    required this.text,\n    required this.expectedResult,\n    required this.minutes,\n    required this.description,\n    required this.checklist,\n  });\n\n  final String text;\n  final String expectedResult;\n  final int minutes;\n  final String description;\n  final List<PathChecklistItemSnapshot> checklist;\n}\n\nenum _PathOptionAction { edit }\n\n/// Options is the visible affordance. Holding the same control starts the\n/// canonical reorder gesture, so Paths keeps drag ordering without exposing a\n/// separate drag icon.\nclass PathOptionsReorderButton extends StatelessWidget {\n  const PathOptionsReorderButton({\n    super.key,\n    required this.index,\n    required this.ru,\n    required this.onEdit,\n    this.tooltip,\n  });\n\n  final int index;\n  final bool ru;\n  final VoidCallback onEdit;\n  final String? tooltip;\n\n  @override\n  Widget build(BuildContext context) {\n    final color = Theme.of(context).colorScheme.onSurfaceVariant;\n    final label = tooltip ?? (ru ? 'Опции' : 'Options');\n    return ReorderableDelayedDragStartListener(\n      index: index,\n      child: PopupMenuButton<_PathOptionAction>(\n        tooltip: '$label · ${ru ? 'удерживайте для перемещения' : 'hold to reorder'}',\n        position: PopupMenuPosition.under,\n        onSelected: (value) {\n          if (value == _PathOptionAction.edit) onEdit();\n        },\n        itemBuilder: (context) => [\n          PopupMenuItem<_PathOptionAction>(\n            value: _PathOptionAction.edit,\n            child: Row(\n              children: [\n                const Icon(Icons.edit_outlined, size: 19),\n                const SizedBox(width: 10),\n                Text(ru ? 'Изменить' : 'Edit'),\n              ],\n            ),\n          ),\n        ],\n        child: MouseRegion(\n          cursor: SystemMouseCursors.basic,\n          child: SizedBox.square(\n            dimension: 36,\n            child: Icon(Icons.more_horiz_rounded, size: 21, color: color),\n          ),\n        ),\n      ),\n    );\n  }\n}\n\nFuture<PathEditDraft?> showPathEditSheet({\n  required BuildContext context,\n  required bool ru,\n  required ProjectPathSnapshot path,\n}) async {\n  final values = await _showTwoFieldSheet(\n    context: context,\n    title: ru ? 'Изменить путь' : 'Edit Path',\n    firstLabel: ru ? 'Название пути' : 'Path name',\n    firstValue: path.name,\n    secondLabel: ru ? 'Цель пути' : 'Path goal',\n    secondValue: path.goal,\n    secondMinLines: 3,\n    saveLabel: ru ? 'Сохранить' : 'Save',\n  );\n  if (values == null) return null;\n  return PathEditDraft(name: values.$1, goal: values.$2);\n}\n\nFuture<PathStageEditDraft?> showPathStageEditSheet({\n  required BuildContext context,\n  required bool ru,\n  required PathStageSnapshot stage,\n}) async {\n  final values = await _showTwoFieldSheet(\n    context: context,\n    title: ru ? 'Изменить этап' : 'Edit stage',\n    firstLabel: ru ? 'Формулировка этапа' : 'Stage wording',\n    firstValue: stage.title,\n    secondLabel: ru ? 'Критерий завершения' : 'Completion criteria',\n    secondValue: stage.completionCriteria,\n    secondMinLines: 3,\n    saveLabel: ru ? 'Сохранить' : 'Save',\n  );\n  if (values == null) return null;\n  return PathStageEditDraft(\n    title: values.$1,\n    completionCriteria: values.$2,\n  );\n}\n\nFuture<PathActionEditDraft?> showPathActionEditSheet({\n  required BuildContext context,\n  required bool ru,\n  required PathActionSnapshot action,\n}) {\n  return showModalBottomSheet<PathActionEditDraft>(\n    context: context,\n    isScrollControlled: true,\n    useSafeArea: true,\n    backgroundColor: Colors.transparent,\n    builder: (sheetContext) => _PathActionEditSheet(\n      ru: ru,\n      action: action,\n    ),\n  );\n}\n\nFuture<(String, String)?> _showTwoFieldSheet({\n  required BuildContext context,\n  required String title,\n  required String firstLabel,\n  required String firstValue,\n  required String secondLabel,\n  required String secondValue,\n  required int secondMinLines,\n  required String saveLabel,\n}) {\n  return showModalBottomSheet<(String, String)>(\n    context: context,\n    isScrollControlled: true,\n    useSafeArea: true,\n    backgroundColor: Colors.transparent,\n    builder: (sheetContext) => _TwoFieldPathEditSheet(\n      title: title,\n      firstLabel: firstLabel,\n      firstValue: firstValue,\n      secondLabel: secondLabel,\n      secondValue: secondValue,\n      secondMinLines: secondMinLines,\n      saveLabel: saveLabel,\n    ),\n  );\n}\n\nclass _TwoFieldPathEditSheet extends StatefulWidget {\n  const _TwoFieldPathEditSheet({\n    required this.title,\n    required this.firstLabel,\n    required this.firstValue,\n    required this.secondLabel,\n    required this.secondValue,\n    required this.secondMinLines,\n    required this.saveLabel,\n  });\n\n  final String title;\n  final String firstLabel;\n  final String firstValue;\n  final String secondLabel;\n  final String secondValue;\n  final int secondMinLines;\n  final String saveLabel;\n\n  @override\n  State<_TwoFieldPathEditSheet> createState() => _TwoFieldPathEditSheetState();\n}\n\nclass _TwoFieldPathEditSheetState extends State<_TwoFieldPathEditSheet> {\n  late final TextEditingController _first =\n      TextEditingController(text: widget.firstValue);\n  late final TextEditingController _second =\n      TextEditingController(text: widget.secondValue);\n\n  @override\n  void dispose() {\n    _first.dispose();\n    _second.dispose();\n    super.dispose();\n  }\n\n  void _save() {\n    final first = _first.text.trim();\n    final second = _second.text.trim();\n    if (first.isEmpty || second.isEmpty) return;\n    Navigator.of(context).pop((first, second));\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return _PathSheetFrame(\n      title: widget.title,\n      saveLabel: widget.saveLabel,\n      onSave: _save,\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.stretch,\n        children: [\n          _PathFieldLabel(widget.firstLabel),\n          TextField(\n            controller: _first,\n            autofocus: true,\n            textInputAction: TextInputAction.next,\n            decoration: const InputDecoration(border: OutlineInputBorder()),\n          ),\n          const SizedBox(height: 22),\n          _PathFieldLabel(widget.secondLabel),\n          TextField(\n            controller: _second,\n            minLines: widget.secondMinLines,\n            maxLines: 8,\n            decoration: const InputDecoration(border: OutlineInputBorder()),\n          ),\n        ],\n      ),\n    );\n  }\n}\n\nclass _ChecklistRowDraft {\n  _ChecklistRowDraft({\n    required this.id,\n    required String text,\n    required this.done,\n  }) : controller = TextEditingController(text: text);\n\n  final String id;\n  final TextEditingController controller;\n  bool done;\n}\n\nclass _PathActionEditSheet extends StatefulWidget {\n  const _PathActionEditSheet({\n    required this.ru,\n    required this.action,\n  });\n\n  final bool ru;\n  final PathActionSnapshot action;\n\n  @override\n  State<_PathActionEditSheet> createState() => _PathActionEditSheetState();\n}\n\nclass _PathActionEditSheetState extends State<_PathActionEditSheet> {\n  late final TextEditingController _text =\n      TextEditingController(text: widget.action.text);\n  late final TextEditingController _result =\n      TextEditingController(text: widget.action.expectedResult);\n  late final TextEditingController _minutes =\n      TextEditingController(text: '${widget.action.minutes}');\n  late final TextEditingController _description =\n      TextEditingController(text: widget.action.description);\n  late final List<_ChecklistRowDraft> _checklist = [\n    for (final item in widget.action.checklist)\n      _ChecklistRowDraft(id: item.id, text: item.text, done: item.isDone),\n  ];\n\n  @override\n  void dispose() {\n    _text.dispose();\n    _result.dispose();\n    _minutes.dispose();\n    _description.dispose();\n    for (final item in _checklist) {\n      item.controller.dispose();\n    }\n    super.dispose();\n  }\n\n  void _addChecklistItem() {\n    setState(() {\n      _checklist.add(\n        _ChecklistRowDraft(\n          id: 'check-${DateTime.now().microsecondsSinceEpoch}',\n          text: '',\n          done: false,\n        ),\n      );\n    });\n  }\n\n  void _removeChecklistItem(int index) {\n    if (index < 0 || index >= _checklist.length) return;\n    final removed = _checklist.removeAt(index);\n    removed.controller.dispose();\n    setState(() {});\n  }\n\n  void _save() {\n    final text = _text.text.trim();\n    final result = _result.text.trim();\n    final minutes = int.tryParse(_minutes.text.trim());\n    if (text.isEmpty ||\n        result.isEmpty ||\n        minutes == null ||\n        minutes < 1 ||\n        minutes > 30) {\n      return;\n    }\n    final checklist = <PathChecklistItemSnapshot>[];\n    for (final item in _checklist) {\n      final value = item.controller.text.trim();\n      if (value.isEmpty) continue;\n      checklist.add(\n        PathChecklistItemSnapshot(\n          id: item.id,\n          text: value,\n          isDone: item.done,\n        ),\n      );\n    }\n    Navigator.of(context).pop(\n      PathActionEditDraft(\n        text: text,\n        expectedResult: result,\n        minutes: minutes,\n        description: _description.text.trim(),\n        checklist: checklist,\n      ),\n    );\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final ru = widget.ru;\n    return _PathSheetFrame(\n      title: ru ? 'Пункт этапа' : 'Stage item',\n      saveLabel: ru ? 'Сохранить' : 'Save',\n      onSave: _save,\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.stretch,\n        children: [\n          _PathFieldLabel(ru ? 'Формулировка' : 'Wording'),\n          TextField(\n            controller: _text,\n            autofocus: true,\n            minLines: 1,\n            maxLines: 4,\n            decoration: const InputDecoration(border: OutlineInputBorder()),\n          ),\n          const SizedBox(height: 20),\n          _PathFieldLabel(ru ? 'Конечный результат' : 'Final result'),\n          TextField(\n            controller: _result,\n            minLines: 2,\n            maxLines: 6,\n            decoration: const InputDecoration(border: OutlineInputBorder()),\n          ),\n          const SizedBox(height: 20),\n          _PathFieldLabel(ru ? 'Описание / контекст' : 'Description / context'),\n          TextField(\n            controller: _description,\n            minLines: 4,\n            maxLines: 12,\n            decoration: InputDecoration(\n              border: const OutlineInputBorder(),\n              hintText: ru\n                  ? 'Что важно знать, ссылки, пояснения, промежуточные детали…'\n                  : 'Context, links, notes and intermediate details…',\n            ),\n          ),\n          const SizedBox(height: 20),\n          Row(\n            children: [\n              Expanded(\n                child: _PathFieldLabel(\n                  ru ? 'Мини-чеклист' : 'Mini checklist',\n                  bottom: 0,\n                ),\n              ),\n              AppButton.ghost(\n                label: ru ? 'Добавить' : 'Add',\n                icon: Icons.add_rounded,\n                size: AppButtonSize.s,\n                onPressed: _addChecklistItem,\n              ),\n            ],\n          ),\n          const SizedBox(height: 8),\n          if (_checklist.isEmpty)\n            Text(\n              ru\n                  ? 'Необязательно. Добавляйте только внутренние шаги, которые помогают выполнить этот пункт.'\n                  : 'Optional. Add only internal steps that help complete this item.',\n              style: Theme.of(context).textTheme.bodySmall?.copyWith(\n                    color: Theme.of(context).colorScheme.onSurfaceVariant,\n                  ),\n            )\n          else\n            for (var index = 0; index < _checklist.length; index++) ...[\n              _PathChecklistEditorRow(\n                key: ValueKey(_checklist[index].id),\n                item: _checklist[index],\n                onChanged: () => setState(() {}),\n                onDelete: () => _removeChecklistItem(index),\n              ),\n              if (index != _checklist.length - 1) const SizedBox(height: 8),\n            ],\n          const SizedBox(height: 20),\n          SizedBox(\n            width: 150,\n            child: Column(\n              crossAxisAlignment: CrossAxisAlignment.start,\n              children: [\n                _PathFieldLabel(ru ? 'Время, мин' : 'Minutes'),\n                TextField(\n                  controller: _minutes,\n                  keyboardType: TextInputType.number,\n                  decoration: const InputDecoration(\n                    border: OutlineInputBorder(),\n                  ),\n                ),\n              ],\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}\n\nclass _PathChecklistEditorRow extends StatelessWidget {\n  const _PathChecklistEditorRow({\n    super.key,\n    required this.item,\n    required this.onChanged,\n    required this.onDelete,\n  });\n\n  final _ChecklistRowDraft item;\n  final VoidCallback onChanged;\n  final VoidCallback onDelete;\n\n  @override\n  Widget build(BuildContext context) {\n    return Row(\n      crossAxisAlignment: CrossAxisAlignment.center,\n      children: [\n        Checkbox(\n          value: item.done,\n          onChanged: (value) {\n            item.done = value == true;\n            onChanged();\n          },\n        ),\n        Expanded(\n          child: TextField(\n            controller: item.controller,\n            minLines: 1,\n            maxLines: 3,\n            decoration: const InputDecoration(\n              isDense: true,\n              border: OutlineInputBorder(),\n            ),\n          ),\n        ),\n        const SizedBox(width: 6),\n        IconButton(\n          tooltip: 'Delete',\n          onPressed: onDelete,\n          icon: const Icon(Icons.close_rounded, size: 19),\n        ),\n      ],\n    );\n  }\n}\n\nclass _PathFieldLabel extends StatelessWidget {\n  const _PathFieldLabel(this.text, {this.bottom = 8});\n\n  final String text;\n  final double bottom;\n\n  @override\n  Widget build(BuildContext context) {\n    return Padding(\n      padding: EdgeInsets.only(bottom: bottom),\n      child: Text(\n        text,\n        style: Theme.of(context).textTheme.labelLarge?.copyWith(\n              fontWeight: FontWeight.w800,\n            ),\n      ),\n    );\n  }\n}\n\nclass _PathSheetFrame extends StatelessWidget {\n  const _PathSheetFrame({\n    required this.title,\n    required this.saveLabel,\n    required this.onSave,\n    required this.child,\n  });\n\n  final String title;\n  final String saveLabel;\n  final VoidCallback onSave;\n  final Widget child;\n\n  @override\n  Widget build(BuildContext context) {\n    final scheme = Theme.of(context).colorScheme;\n    final bottom = MediaQuery.viewInsetsOf(context).bottom;\n    return AnimatedPadding(\n      duration: const Duration(milliseconds: 160),\n      curve: Curves.easeOut,\n      padding: EdgeInsets.only(bottom: bottom),\n      child: Align(\n        alignment: Alignment.bottomCenter,\n        child: FractionallySizedBox(\n          heightFactor: .92,\n          child: ConstrainedBox(\n            constraints: const BoxConstraints(maxWidth: 820),\n            child: Material(\n              color: scheme.surface,\n              borderRadius: const BorderRadius.vertical(\n                top: Radius.circular(24),\n              ),\n              clipBehavior: Clip.antiAlias,\n              child: Column(\n                children: [\n                  Padding(\n                    padding: const EdgeInsets.fromLTRB(12, 10, 16, 10),\n                    child: Row(\n                      children: [\n                        IconButton(\n                          tooltip: 'Close',\n                          onPressed: () => Navigator.of(context).pop(),\n                          icon: const Icon(Icons.close_rounded),\n                        ),\n                        const SizedBox(width: 4),\n                        Expanded(\n                          child: Text(\n                            title,\n                            style: Theme.of(context)\n                                .textTheme\n                                .titleLarge\n                                ?.copyWith(fontWeight: FontWeight.w800),\n                          ),\n                        ),\n                        AppButton.primary(\n                          label: saveLabel,\n                          size: AppButtonSize.s,\n                          onPressed: onSave,\n                        ),\n                      ],\n                    ),\n                  ),\n                  const Divider(height: 1),\n                  Expanded(\n                    child: SingleChildScrollView(\n                      padding: const EdgeInsets.fromLTRB(24, 24, 24, 40),\n                      child: child,\n                    ),\n                  ),\n                ],\n              ),\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n}\n")

app_structure = Path('docs/APP_STRUCTURE.md')
text = app_structure.read_text()
if 'features/paths/widgets/path_edit_sheet.dart' not in text:
    rows = text.splitlines()
    for i, line in enumerate(rows):
        if 'features/paths/widgets/path_stage_card.dart' in line:
            rows.insert(i + 1, '| `features/paths/widgets/path_edit_sheet.dart` | Path / stage / action editor sheets, item mini-checklist + description editor, and Options-as-delayed-reorder control |')
            break
    else:
        raise SystemExit('Path stage card row not found in docs/APP_STRUCTURE.md')
    app_structure.write_text('\n'.join(rows) + '\n')

variant = Path('docs/PATHS_STAGE_CARD_VARIANT_2.md')
text = variant.read_text()
if 'Options control and detailed editing' not in text:
    text += '''\n## Options control and detailed editing\n\nThe visible drag glyph is replaced by an **Options** control for every stage and every stage item. A normal click/tap opens editing. Holding the same control starts the canonical reorder gesture, so ordering remains available without a separate drag icon.\n\nStage editing changes the stage wording and completion criterion. Item editing owns four content levels: formulation, final expected result, optional description/context, and an optional mini-checklist. The Path heading is a first-class editable name, separate from the Path goal; both are revisioned with the rest of Path content.\n'''
    variant.write_text(text)

design = Path('docs/DESIGN_SYSTEM.md')
text = design.read_text()
if 'Options-as-reorder control' not in text:
    text += '''\n### Paths: Options-as-reorder control\n\nFor ordered Path stages/items, show `more_horiz` as the visible Options affordance. Tap/click opens Edit; press-and-hold on the same control invokes the canonical reorder listener. Do not show a second drag glyph beside Options. Path item detail editing uses a sheet with formulation, final result, optional description/context, optional mini-checklist, and time estimate.\n'''
    design.write_text(text)
